    companies_house_key: config.COMPANIES_HOUSE_API_KEY
  }
}));

// 3. Phone Classification & Pre-Qualification
const lead = $input.item.json;
const rawPhone = String(lead.phone || '').trim();
const digits = rawPhone.replace(/[^0-9]/g, '');

let phoneType = 'unknown';
let isWhatsAppViable = false;
let standardizedPhone = rawPhone;

if (digits.length >= 7) {
  if (digits.startsWith('0')) {
    standardizedPhone = '+44' + digits.substring(1);
  } else if (digits.startsWith('44')) {
    standardizedPhone = '+' + digits;
  }

  if (digits.startsWith('447') || digits.startsWith('07')) {
    phoneType = 'uk_mobile';
    isWhatsAppViable = true;
  } else if (digits.startsWith('441') || digits.startsWith('442') || digits.startsWith('01') || digits.startsWith('02')) {
    phoneType = 'uk_landline';
    isWhatsAppViable = false;
  }
}

const hasValidWebsite = Boolean(
  lead.website && 
  lead.website !== 'None' && 
  lead.website !== 'NO WEBSITE' && 
  !lead.website.toLowerCase().includes('facebook.com')
);

const chBasicAuth = Buffer.from((lead.companies_house_key || '') + ':').toString('base64');

return {
  json: {
    ...lead,
    phone: standardizedPhone,
    phone_type: phoneType,
    is_whatsapp_viable: isWhatsAppViable,
    has_valid_website: hasValidWebsite,
    outreach_channel: isWhatsAppViable ? 'whatsapp' : 'email_or_phone',
    ch_auth_header: 'Basic ' + chBasicAuth
  }
};

// Merge Companies House Official Data into Lead
const prev = $node['3. UK Phone Classifier & Filter'].json;
const chResponse = $input.item.json;

let companyNumber = null;
let companyStatus = 'active';
let dateOfCreation = null;
let officialAddress = null;

if (chResponse && chResponse.items && chResponse.items.length > 0) {
  const bestMatch = chResponse.items[0];
  companyNumber = bestMatch.company_number || null;
  companyStatus = bestMatch.company_status || 'active';
  dateOfCreation = bestMatch.date_of_creation || null;
  if (bestMatch.address_snippet) {
    officialAddress = bestMatch.address_snippet;
  }
}

return {
  json: {
    ...prev,
    company_number: companyNumber,
    company_status: companyStatus,
    date_of_creation: dateOfCreation,
    official_ch_address: officialAddress || prev.address,
    companies_house_verified: Boolean(companyNumber)
  }
};

